Given a sorted array arr[] of size n, the goal is to rearrange the array so that all distinct elements appear at the beginning in sorted order. Additionally, return the length of this distinct sorted subarray.Note: The elements after the distinct ones can be in any order and hold any value, as they don't affect the result.Examples: Input: arr[] = [2, 2, 2, 2, 2]Output: [2]Explanation: All the elements are 2, So only keep one instance of 2.Input: arr[] = [1, 2, 2, 3, 4, 4, 4, 5, 5]Output: [1, 2, 3, 4, 5]Input: arr[] = [1, 2, 3]Output: [1, 2, 3]Explanation : No change as all elements are distinct.Try It YourselfTable of ContentUsing Hash Set - Works for Unsorted Also - O(n) Time and O(n) SpaceExpected Approach - O(n) Time and O(1) SpaceUsing Hash Set - Works for Unsorted Also - O(n) Time and O(n) SpaceUse a hash set or dictionary to store elements already processedInitialize index of result array as 0.Traverse through the input array. If an element is not in the hash set, put it at the result index and insert into the set.
            C++

    #include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;

int removeDuplicates(vector<int>& arr) {

    // To track seen elements
    unordered_set<int> s; 

    // To maintain the new size of the array
    int idx = 0;  

    for (int i = 0; i < arr.size(); i++) {
        if (s.find(arr[i]) == s.end()) { 
            s.insert(arr[i]);  
            arr[idx++] = arr[i];  
        }
    }

    // Return the size of the array 
    // with unique elements
    return s.size(); 
}

int main() {
    vector<int> arr = {1, 2, 2, 3, 4, 4, 4, 5, 5};
    int newSize = removeDuplicates(arr);
    for (int i = 0; i < newSize; i++) 
        cout << arr[i] << " ";
    return 0;
}


